export interface ApiComputersCreateRequest {
  server_id: string;
  /**
   * Name for the computer. Must be 3-100 characters, alphanumeric with hyphens and underscores. Omit or use "rand" to generate a random name.
   * @minLength 3
   * @maxLength 100
   * @pattern ^[a-zA-Z0-9-_]+$
   */
  name?: string;
  /**
   * HEX color for the computer (e.g., #FF0000 or FF0000). If not provided, a random color will be generated. The # prefix will be added automatically if missing, and the color will be converted to uppercase.
   * @pattern ^#[0-9A-Fa-f]{3}$|^#[0-9A-Fa-f]{6}$|^[0-9A-Fa-f]{3}$|^[0-9A-Fa-f]{6}$
   */
  color?: string;
  /**
   * Computer image to use. If null or not provided, will use the default configured image. Shorthand is resolved automatically: a bare distribution name or a hyphenated version ("debian", "debian-13") becomes the canonical base image ("debian/13"), as do the "debian:13" and "debian 13" forms.
   * @maxLength 255
   */
  computer_image?: string | null;
  /** Whether AI features are enabled (default: true) */
  ai?: boolean;
  /** The computer's initial environment variables. Keys must match `^[a-zA-Z_][a-zA-Z0-9_]*$` and be at most 128 characters long. */
  environment_vars?: Record<string, string>;
  /** SSH public key for computer access. SSH public keys must be unique per computer (one computer per key). If not provided, will inherit from project defaults. */
  ssh_public_key?: string | null;
  /**
   * Optional comment for the computer (max 16000 characters)
   * @maxLength 16000
   */
  comment?: string | null;
  /** Enable all Hoody Kit features: extra package sources, a package download cache, basic and developer packages, extra shells, the Hoody daemon, sudo setup, snapd removal, web view, desktop, a default user, a web terminal, and VM tooling (about 185 MiB; running VMs additionally needs the separate kvm grant). */
  hoody_kit?: boolean;
  /** Enable dev_kit development tools in the computer. Defaults to true when hoody_kit is true, false when hoody_kit is false (unless explicitly set). Cannot be updated after creation. */
  dev_kit?: boolean;
  /** Enable /dev/kvm passthrough (run full VMs inside the computer) at creation. Available on rented / dedicated (bare-metal) servers ONLY (never free tier), and rejected (403) on a free server. Defaults to false. Can also be toggled later via PUT /api/v1/computers/{id}/kvm on a stopped computer. */
  kvm?: boolean;
  /** Accepted alias of `kvm` on input (`kvm` wins if both are sent and they must agree). */
  dev_kvm?: boolean;
  /** Whether the computer should start automatically on host boot (default: true) */
  autostart?: boolean;
  /** Whether to mount a ramdisk at /ramdisk in the computer (default: true). The ramdisk KEEPS data when you stop/start/reboot the computer, but LOSES data if the physical host server reboots. Can store up to 50% of total host memory. Ideal for security (data automatically wiped on server seizure), temporary files, or extremely fast I/O at no cost. */
  ramdisk?: boolean;
  /** Realm IDs to assign this computer to. If creating from a realm subdomain (a 24-character hex realm id, e.g., https://0123456789abcdef01234567.api.hoody.com), the subdomain realm is automatically included and merged with any explicitly provided realm_ids. Note: Computers can have different realm membership than their parent project. */
  realm_ids?: string[];
}

