  statusCode: 201;
  message: string;
  data: { id?: string; project_id?: string; computer_id?: string; alias?: string; program?: string; index?: number /* min: 1 */; target_path?: string | null; allow_path_override?: boolean; expires_at?: string | null; enabled?: boolean; created_at?: string; updated_at?: string; server_id?: string | null; server_name?: string | null; subserver_name?: string; url?: string | null };
