export interface ApiProxyAliasesUpdateRequest {
  /**
   * New alias name. Two independent uniqueness rules apply, either of which answers 409 ALIAS_IN_USE: the name must be free on the computer's physical server (across every tenant hosted there), AND your own account may hold a given name only once across all servers. Reserved and rejected: the exact label "computers" (an infrastructure label of the computer proxy domain), and anything equal to a reserved service name (such as "egress") or starting with that name followed by "-" (such as "egress-"). Distinct labels such as "computers-my-app" and "egressmyapp" are allowed. A name another account released in the last 90 days on the same physical server, or from a computer that was deleted, is also refused with 409 ALIAS_IN_USE.
   * @minLength 3
   * @maxLength 61
   * @pattern ^[a-z0-9]([a-z0-9-]*[a-z0-9])?$
   */
  alias?: string;
  /** Program or protocol the alias targets: a built-in Hoody program ("terminal", "files", "code", …) or a transport protocol ("http", "https", "ssh"). Use "http"/"https" with the "port" field to reach an HTTP server running on that port inside the computer (e.g. program "http" + port 3000). The combined "http-3000" form and "index"-as-port also work; order of authority is port > embedded "http-<port>" > index. Switching an alias from a built-in program to "http"/"https" needs a port in the same request (400 PORT_REQUIRED). Must be a known Hoody program name (or one of its aliases) or protocol. */
  program?: string;
  /**
   * Target port for the "http"/"https" protocol: the port your server listens on inside the computer (e.g. program "http" + port 3000). Preferred over "index"; takes precedence over "index" and over any port embedded in the program string. Ignored for built-in Hoody programs.
   * @minimum 1
   * @maximum 65535
   */
  port?: number /* min: 1, max: 65535 */;
  /**
   * Instance index, or target port when program is "http"/"https". Prefer the dedicated "port" field; if "port" or a port embedded in the program ("http-3000") is also supplied, that wins over this index.
   * @minimum 1
   */
  index?: number /* min: 1 */;
  /**
   * Landing path served for root requests, with its own query. With allow_path_override true, requests carrying their own path are forwarded as-sent (never a prefix); with false, it is the only path served. Set to null to remove it.
   * @maxLength 2048
   */
  target_path?: string | null;
  /** When false, only the root, or target_path itself, is served, as target_path; other paths 404, and target_path's own parameters cannot be overridden. When true, a request that carries its own path is forwarded as sent. */
  allow_path_override?: boolean;
  /** Expiration date in the future: an ISO 8601 string or a Unix timestamp in seconds or milliseconds; null removes the expiration. A date that is not in the future is refused with 400. */
  expires_at?: string | number /* min: 0 */ | null;
  /** Whether the alias is enabled */
  enabled?: boolean;
}

