export interface ApiStorageSharesCreateRequest {
  /**
   * Absolute path in the source computer. The source computer controls WHAT to share (this path); target mount paths are set automatically, NOT by users. At most 1000 characters. Allowed characters: a-z A-Z 0-9 / - _ . ( ). The path is normalized (repeated slashes collapse). Refused: `.` or `..` segments, any name containing `..`, null bytes, the root (/), /hoody, and paths at or below /proc, /sys, /dev, /boot, /run, /var/run, /hoody/shares and /hoody/containers. Returns the normalized canonical path.
   * @minLength 1
   * @maxLength 1000
   * @pattern ^/.*
   */
  source_path: string;
  /**
   * 1:1 Computer Share: Share with a specific computer. Specify this OR target_project_id, not both.
   * @pattern ^[0-9a-f]{24}$
   */
  target_computer_id?: string;
  /**
   * Project-Wide Share: Share with all computers in a project. Mounts on every current and future computer of that project except the source computer; a receiving computer can opt out. Specify this OR target_computer_id, not both.
   * @pattern ^[0-9a-f]{24}$
   */
  target_project_id?: string;
  /** Mount mode - readonly (read-only) or readwrite (read-write) */
  mode: "readonly" | "readwrite";
  /**
   * Optional alias: 3 to 63 lowercase letters, digits, hyphens or underscores, starting and ending with a letter or digit.
   * @minLength 3
   * @maxLength 63
   * @pattern ^[a-z0-9][a-z0-9_-]*[a-z0-9]$
   */
  alias?: string;
  /**
   * Optional label for organizing shares: 3 to 63 lowercase letters, digits, hyphens or underscores, starting and ending with a letter or digit.
   * @minLength 3
   * @maxLength 63
   * @pattern ^[a-z0-9][a-z0-9_-]*[a-z0-9]$
   */
  label?: string;
  /**
   * Optional description
   * @maxLength 1000
   */
  description?: string;
  /** Whether to enable the share (default: true). Disabled shares are kept but not mounted. */
  enabled?: boolean;
  /**
   * Unix timestamp in whole seconds, strictly in the future; a fraction or a past time is refused with 422. Leave it out for a share that never expires.
   * @minimum 1
   */
  expires_at?: number /* min: 1 */;
}

