export interface ApiWalletCreditsTransferRequest {
  /**
   * USD amount as a string with up to 2 decimals, e.g., "10.00". No exponent, no negatives. The transfer fee is rounded up to a whole cent, so every transfer with a fee pays at least 0.01; an amount so small that no AI credit would be left after the fee is refused (400).
   * @pattern ^(0|[1-9]\d*)(\.\d{1,2})?$
   */
  amount: string;
  /**
   * Optional caller idempotency key. Retrying with the SAME key AND same amount returns the original receipt without moving funds again; the same key with a different amount is rejected (409 TRANSFER_IDEMPOTENCY_KEY_REUSED). Always send one: it makes a double-click or retry-after-timeout safe, and a caller that cannot read balances re-applies a pending spending-limit update by sending the same request again with the same key.
   * @minLength 1
   * @maxLength 128
   * @pattern \S
   */
  idempotency_key?: string;
  /**
   * The platform fee in basis points that the user was shown and confirmed (the current fee is `ai_credit_fee_bps` of GET /api/v1/wallet/payment-availability). Required while a fee applies: without it the transfer is refused (409 TRANSFER_FEE_CONFIRMATION_REQUIRED). A value that is not the current fee is refused (409 TRANSFER_FEE_CHANGED), so the user confirms again. Both refusals carry the current fee in `data.current_fee_bps`. It may be left out while the fee is 0. Not checked on an idempotent replay: the same idempotency_key and amount return the original receipt even if the fee changed since.
   * @minimum 0
   * @maximum 9999
   */
  expected_fee_bps?: number /* min: 0, max: 9999 */;
}

