export interface ApiAuthSignupRequest {
  /**
   * Email address for the new account
   * @maxLength 255
   */
  email: string;
  /**
   * Password (min 12 chars, at most 72 UTF-8 bytes, at least 3 of the 4 character classes: uppercase, lowercase, number, special)
   * @minLength 12
   * @maxLength 128
   */
  password: string;
  /**
   * Optional preferred server region (e.g., "eu-west"). If omitted, auto-assigned by GeoIP proximity.
   * @maxLength 50
   * @pattern ^[a-z0-9-]+$
   */
  region?: string;
  /**
   * Optional invite code ("coupon") captured from the signup link. Remembered and applied automatically after email verification, not validated at signup.
   * @minLength 1
   * @maxLength 128
   */
  invite_code?: string;
  /**
   * Optional referral code from a referral link or typed by the person signing up. An unknown or inactive code is ignored; the signup answer is the same either way.
   * @maxLength 64
   */
  referral_code?: string;
  /** How the referral code arrived: from a referral link, or typed by the person signing up. Defaults to link. */
  referral_source?: "link" | "typed";
  /**
   * Optional client-declared source channel for analytics: web | ssh | webssh | cli | sdk | agent. Unrecognised values are recorded as "unknown"; never affects account behaviour.
   * @maxLength 64
   */
  client?: string;
  /** From a CHALLENGE_REQUIRED answer, once the person finished the check */
  challenge?: { token: string; secret: string };
  /**
   * Optional token from the sign-up page's browser check (web form only). Clients without a browser leave it out; an unreadable one is ignored.
   * @maxLength 4096
   */
  observation?: string;
}

