/**
 * What to scan and how to label the generated document. Every field is optional: `null` takes the default, as does an empty string for a text field, and a value of the wrong type is refused with a 400.
 */
export interface ExecOpenapiGenerateRequest {
  /** Directory relative to the selected execution namespace, or already prefixed with that namespace. Default `scripts` selects the namespace root, or the scripts root when no namespace applies. Leading slashes are dropped, so an absolute filesystem path is not supported. */
  directory?: string | null;
  /** Alternative to `directory`. Only the first entry is scanned, and only when `directory` is not given; use `/user-openapi/merge` to combine several directories. */
  directories?: string[] | null;
  /**
   * Subdomain namespace: letters, digits, dots, hyphens and underscores, not made only of dots and not a reserved directory name (`node_modules`, `.git`, `.hoody-cache`, `_sdk`, `_hoody`, in any case); it is lowercased. Surrounding whitespace is ignored. When omitted, `null` or empty, it is taken from the Host header. Any other value is refused with a 400.
   * @pattern ^\s*(?:(?!(?:\.+|[nN][oO][dD][eE]_[mM][oO][dD][uU][lL][eE][sS]|\.[gG][iI][tT]|\.[hH][oO][oO][dD][yY]-[cC][aA][cC][hH][eE]|_[sS][dD][kK]|_[hH][oO][oO][dD][yY])\s*$)[A-Za-z0-9._-]+)?\s*$
   */
  subdomain?: string | null;
  /**
   * Exec ID namespace: 1 to 64 letters or digits, with no dots, hyphens or underscores (a hostname cannot carry them); it is lowercased. Surrounding whitespace is ignored. When omitted, `null` or empty, it is taken from the Host header. Any other value is refused with a 400.
   * @pattern ^\s*(?:[A-Za-z0-9]{1,64})?\s*$
   */
  execId?: string | null;
  /** Scan subdirectories. */
  recursive?: boolean | null;
  /** File-name globs to include. Default `["*.js", "*.ts"]`. */
  includePatterns?: string[] | null;
  /** File-name globs to skip. Default `["*.test.js", "*.spec.ts", "*.test.ts", "*.spec.js"]`. */
  excludePatterns?: string[] | null;
  /** Document `info.title`. */
  title?: string | null;
  /** Document `info.description`. */
  description?: string | null;
  /** Document `info.version`. */
  version?: string | null;
  /** URL of the document's only `servers` entry. Omitted, it is this deployment's own origin, as the request reached it. */
  baseUrl?: string | null;
}

export interface ExecOpenapiGenerateResponse {
  statusCode: number;
  message: string;
  data: { success: boolean; data: Record<string, unknown>; meta: { pathCount?: number; scanDirectory?: string; generatedAt?: string } };
}

