export interface ExecSdksImportRequest {
  /**
   * Exec ID the SDK is imported under: 1 to 64 lowercase letters or digits. When omitted, it is taken from the Host header.
   * @maxLength 64
   * @pattern ^[a-z0-9]+$
   */
  execId?: string | null;
  /**
   * HTTPS URL of the OpenAPI document to import. It must name a domain (not an IP address), use port 443, and end in `.json`, `.yaml`, `/documentation/json` or `/documentation/yaml`.
   * @minLength 1
   */
  source_url: string;
  /** Credentials sent when fetching `source_url`: either `{"type": "bearer", "token": "…"}` or `{"type": "basic", "username": "…", "password": "…"}`. Credentials that could not be sent as given are refused with a 400, never dropped. Other members are ignored. */
  source_auth?: (({ type: "bearer" | "basic"; token?: string; username?: string; password?: string }) & ({ type?: "bearer"; token: string } | { type?: "basic"; username: string; password: string })) | null;
  /** Middleware written next to the generated proxy files. Each member is JavaScript source, written as `pre.js` or `post.js` into every directory that receives a proxy. A member that is omitted, `null` or an empty string sends no new source: a re-import keeps the installed middleware, and a proxy directory that has none of that name gets a copy of the one at the SDK root. The source runs as the body of a function with `req` and `res` in scope; it is not a module, so do not `export` a function. Example: `req.headers["x-trace"] = "1";`. */
  middleware?: { pre?: string | null; post?: string | null } | null;
  /** Magic-comment directives written into every generated proxy file, keyed by directive name. Only the members listed here are accepted; any other key is refused with a 400, and so is a value that would not read back from the generated file as sent. When omitted or `null`, a re-import keeps the directives the previous import stored. */
  magic_comments?: { enabled?: boolean | null; token?: string | null | string[]; mode?: "worker" | "serverless" | null; timeout?: number /* min: 0, max: 2147483647 */ | null | string; "log-level"?: "none" | "minimal" | "standard" | "full" | "debug" | null; concurrent?: boolean | null | number /* min: 1, max: 9007199254740991 */; cors?: string | null; websocket?: boolean | null } | null;
  /** Overwrite conflicting files (untracked files, and files changed since the last import) instead of answering 409 with a dry-run report. */
  force?: boolean | null;
}

