export interface AgentLoopsCreateRequest {
  /** The prompt fired each loop run. */
  prompt: string;
  /** Run interval as a duration token, for example "30m". Required, with no default: a create without it is rejected. The minimum accepted interval is 60 seconds: a shorter one is refused rather than rounded up. */
  interval: string;
  /** Stop after this many runs. Omitted, 0 or negative applies the default ceiling of 50 runs; there are no unbounded loops. */
  max_runs?: number;
  /** Optional stop predicate, evaluated after each run. Omit the field entirely when there is no predicate: a string value is rejected, and that includes the empty string. */
  stop_when?: { kind?: "expression" | "toolCall" | "judgeRef" | "convergence"; expr?: string; tool?: string; check?: string; judge?: string; args?: Record<string, unknown>; threshold?: number; min_iters?: number; allow_network?: boolean };
  /** Cost ceiling in USD, a number >= 0. 0 or absent means unlimited. It counts priced usage only: a Claude Code session's fires are unpriced (their usage carries no cost), so there the ceiling never stops the loop; bound such a loop with max_runs or max_wall_ms. A value that is not a JSON number (a string such as "5", true or null) or is negative is refused with 400 bad_request. */
  max_cost_usd?: number;
  /** Wall-clock ceiling, as a whole number of milliseconds from 0 up to (not including) 2^63. 0 or absent means unlimited. Any other value (a string such as "2h", a fraction, a negative number, true or null) is refused with 400 bad_request. */
  max_wall_ms?: number;
  /** Optional expiration as a duration from now, in the same grammar as interval (for example "2h" or "3 days"); omitted, "", "never", "none" or "off" (case-insensitive) means no expiration. An expired loop stops firing. Without fire_now an expiry shorter than one interval is rejected, because the loop would never fire; with fire_now it must be at least 2 seconds, so the immediate first run can happen. */
  expires_in?: string;
  /** Run the first fire on the next scheduler tick instead of one interval out; later fires keep the normal cadence. Default false. */
  fire_now?: boolean;
}

/**
 * The operation's JSON reply, passed through verbatim.
 */
export interface AgentLoopsCreateResponse {
  statusCode: number;
  message: string;
  data: Record<string, unknown>;
}

export interface AgentLoopsUpdateRequest {
  /** Run-state intent (true pauses, false resumes). */
  paused?: boolean;
  /** Expiry intent: a duration-from-now token, e.g. "2h"; "" or "never" clears it. */
  expires_in?: string;
  /** Budget intent: the cost ceiling in USD, a number >= 0; 0 = unlimited. A budget update sets both ceilings: sent without max_wall_ms, it also sets the wall-clock ceiling to 0 (unlimited). A value that is not a JSON number (a string such as "5", true or null) or is negative is refused with 400 bad_request, and nothing changes. */
  max_cost_usd?: number;
  /** Budget intent: the wall-clock ceiling, as a whole number of milliseconds from 0 up to (not including) 2^63; 0 = unlimited. Any other value (a string such as "2h", a fraction, a negative number, true or null) is refused with 400 bad_request, and nothing changes. A budget update sets both ceilings: sent without max_cost_usd, it also sets the cost ceiling to 0 (unlimited). */
  max_wall_ms?: number;
  /** Precondition (any intent): the loop's state as listed (running, firing, paused, error, expired, stopped, ended). When the loop is not in it now, nothing changes and the answer is 409 loop_changed. if_state stopped with the budget fields starts a stopped loop again only if it is still stopped. */
  if_state?: string;
  /** Precondition (any intent): the loop's cost ceiling as listed (0 = none). When it differs now, nothing changes and the answer is 409 loop_changed. */
  if_max_cost_usd?: number;
  /** Precondition (any intent): the loop's wall-clock ceiling in ms as listed (0 = none). When it differs now, nothing changes and the answer is 409 loop_changed. */
  if_max_wall_ms?: number;
}

/**
 * The operation's JSON reply, passed through verbatim.
 */
export interface AgentLoopsUpdateResponse {
  statusCode: number;
  message: string;
  data: Record<string, unknown>;
}

