export interface ProxyAlias {
  /**
   * Unique proxy alias identifier
   * @pattern ^[0-9a-f]{24}$
   */
  id: string;
  /**
   * Owner user ID
   * @pattern ^[0-9a-f]{24}$
   */
  user_id?: string;
  /**
   * Associated project ID
   * @pattern ^[0-9a-f]{24}$
   */
  project_id: string;
  /**
   * Target computer ID
   * @pattern ^[0-9a-f]{24}$
   */
  computer_id: string;
  /** Custom domain alias (custom or auto-generated 48-char hex). Creates URL: https://{alias}.{server_name}.computers.hoody.com/ instead of default https://{projectId}-{computerId}.{server_name}.computers.hoody.com/ */
  alias: string;
  /** Program or protocol the alias targets: a built-in Hoody program (e.g. "terminal", "files", "code") or a transport protocol ("http", "https", "ssh"). For "http"/"https", index is the target port your server listens on inside the computer. */
  program: string;
  /**
   * Instance index (1-based), or the target port when program is "http"/"https".
   * @minimum 1
   */
  index: number /* min: 1 */;
  /** Landing path served when the alias is opened with no path (a root request), e.g. "/api/v1"; a query written in it is sent too. With allow_path_override true, requests that carry their own path are forwarded as-sent, resolved from the computer root, and target_path is never used as a path prefix. With allow_path_override false, it is the only path the alias serves. */
  target_path?: string | null;
  /** When false, the alias serves only the root, or target_path itself: once the proxy permissions allow the request, a request to either lands on target_path and any other path is refused (404). A parameter written in target_path always keeps its value, the visitor's other parameters are passed on, and the method, request body and WebSocket upgrade are forwarded as sent. When true (the default), a root request lands on target_path with its query plus the visitor's parameters, and a request that carries its own path is forwarded as sent. Either way anyone who has the link can open the alias: use proxy permissions to restrict who may. */
  allow_path_override: boolean;
  /** ISO 8601 expiration date, or null if it never expires */
  expires_at?: string | null;
  /** Whether the alias is active. Disabled aliases return 404. */
  enabled: boolean;
  /** Realm IDs this proxy alias belongs to */
  realm_ids?: string[];
  /** ISO 8601 creation timestamp */
  created_at: string;
  /** ISO 8601 last modification timestamp */
  updated_at: string;
  /**
   * ID of the server resource you own. For computers on a subserver, this is the subserver ID; for computers on a physical host, this is the physical server ID.
   * @pattern ^[0-9a-f]{24}$
   */
  server_id?: string | null;
  /** Routable hostname label for URL construction. Always the physical (parent) server name, even for subserver computers. */
  server_name?: string | null;
  /** Display name of the subserver. Present only when the computer is on a subserver; omitted otherwise. */
  subserver_name?: string;
  /** Complete ready-to-use proxy alias URL */
  url?: string | null;
}

