  /** Reasoning/thinking stream chunk. */
  "event.thinking_chunk": { text: string; helper_id?: string; parent_tool_call_id?: string };
  /** Thinking stall warning. */
  "event.thinking_stall": Record<string, unknown>;
  /** TODO list updated. */
  "event.todo_list_updated": Record<string, unknown>;
  /** Tool invocation. */
  "event.tool_call": { tool_id: string; name: string; arguments?: Record<string, unknown>; summary: string; reason?: string; timeout_sec?: number; reason_not_read_file?: string; reason_not_edit_file?: string; reason_not_glob_files?: string; reason_to_increase_timeout?: string; helper_id?: string; parent_tool_call_id?: string };
  /** Tool mode changed/locked. */
  "event.tool_mode": { tool_mode: string; locked: boolean };
  /** Tool result. */
  "event.tool_result": { tool_id: string; name: string; output: string; is_error: boolean; detail?: string; error_code?: string; hint?: string; hint_cmd?: string; elapsed_ms?: number; exit_code?: number; truncated?: boolean; original_bytes?: number; helper_id?: string; parent_tool_call_id?: string; rules?: { rule_ids: string[]; outcome: "deny" | "unchecked"; reason?: string } };
  /** The result of one trim, naming the request id the trim carried: done, refused (turn_in_flight, delegated_session or session_closed; nothing changed), failed (nothing was trimmed) or outcome_unknown (the trim may have been saved; the session sends nothing until it can save its state). Never an error event: another client's trim does not fail this client's turn. */
  "event.trim_result": { request_id?: string; turn_idx: number; outcome: "done" | "refused" | "failed" | "outcome_unknown"; code?: string; message?: string };
  /** A prompt or workflow dispatch was accepted but discarded without running, because it was queued while another client's turn waited on a confirmation or question. It closes that dispatch only (its turn_id); the waiting turn keeps running and no event.agent_done is sent for the discarded one. */
  "event.turn_discarded": { turn_id?: string; outcome?: "cancelled"; error_code?: string };
  /** Echo of the user's input. */
  "event.user_echo": { text?: string; echo_tag?: string; loop_id?: string; run?: number; task_ids?: string[]; auto_model?: string; auto_round?: number; attachments?: { name: string; media_type?: string; size?: number; delivered: boolean }[]; turn_id?: string };
  /** Question posed to the user (parks a gate). On a helper_gates session a helper's question carries helper_id, parent_tool_call_id and, for a background helper, task_id; it parks beside the session's own gate and is answered by its own id. */
  "event.user_question": { question: string; options: string[] | null; rich_options?: { title: string; description: string; has_user_input?: boolean }[]; placeholder?: string; category?: string; frame_request?: { kind: "view" | "bot.dispatch" | "bot.message" | "bot.stop" | "bot.delegates" | "bot.answer_gate" | "bot.peek" | "bot.wait"; request: string; id: string; tool_use_id?: string }; questions?: { id: string; category: string; question: string; options?: string[] }[]; question_id?: number; task_id?: string; helper_id?: string; parent_tool_call_id?: string };
  /** Verbosity setting changed. */
  "event.verbosity": Record<string, unknown>;
