  /** Conversation cleared. */
  "clear": { session_id: string; seq: number; incarnation?: string; turn_id?: string; gate?: Record<string, unknown>; event: { type: "event.clear"; data: Record<string, unknown> } };
  /** Commands sent with POST /api/v1/agent/sessions/{id}/commands reached the session: messages added to the conversation (how next_step inside the running turn, new_turn in a turn of their own, with turn_id), or a stop carried out (how stop, with what it stopped). Carries command_ids. */
  "command_committed": { session_id: string; seq: number; incarnation?: string; turn_id?: string; gate?: Record<string, unknown>; event: { type: "event.command_committed"; data: { command_ids: string[]; turn_id?: string; how: "next_step" | "new_turn" | "stop"; stopped?: ({ kind: "session" | "task" | "workflow_run" | "bash_job" | "loop"; id: string; outcome: "stopped" | "already_done" | "failed"; detail?: string; cleanup?: "detached_may_survive" })[]; cleanup?: "detached_may_survive" } } };
  /** Commands sent with POST /api/v1/agent/sessions/{id}/commands ended without reaching the session: superseded by a stop, refused (a hook blocked them, the session closed, or the session cannot take them) or failed (the session could not record them). Carries command_ids, state and reason. */
  "command_settled": { session_id: string; seq: number; incarnation?: string; turn_id?: string; gate?: Record<string, unknown>; event: { type: "event.command_settled"; data: { command_ids: string[]; state: "superseded" | "refused" | "failed"; reason?: "stop" | "order" | "hook" | "closed" | "unsupported" | "write_failed"; detail?: string; superseded_by?: string } } };
  /** A waiter this session owns (POST /api/v1/agent/sessions/{id}/waiters) ended: an outcome was found, or it timed out, was cancelled, or its target closed. Carries the waiter. */
  "waiter_done": { session_id: string; seq: number; incarnation?: string; turn_id?: string; gate?: Record<string, unknown>; event: { type: "event.waiter_done"; data: { waiter: { waiter_id: string; label?: string; owner: string; target: string; outcomes: ({ name: string; when?: string; match?: { kind: "tool_result" | "tool_call" | "gate" | "turn_end"; tool?: string; exit_code?: number; is_error?: boolean; text_contains?: string; outcome?: "completed" | "failed" | "cancelled" } })[]; from?: string; state: "waiting" | "done"; outcome?: string; reason?: string; also_found?: string[]; evidence?: { seq: number; turn_id?: string; kind: "tool_result" | "tool_call" | "gate" | "turn_end"; tool?: string; exit_code?: number; is_error?: boolean; excerpt?: string; by: "match" | "judge"; p?: number }; on_timeout?: "continue" | "stop" | "ask"; created_at: string; deadline_at: string; ended_at?: string; elapsed_ms?: number; max_checks: number; checks: number; items_seen: number; gap?: boolean; cost_usd: number; cost_known: boolean; model?: string } } } };
  /** Context window compacted. */
