  /** Tool/plan confirmation requested (parks a gate). On a helper_gates session a helper's request carries helper_id, parent_tool_call_id and, for a background helper, task_id; it parks beside the session's own gate and is answered by its own id. */
  "confirm_request": { session_id: string; seq: number; incarnation?: string; turn_id?: string; gate?: Record<string, unknown>; event: { type: "event.confirm_request"; data: { tool_name: string; params: Record<string, unknown> | null; requested_dirs?: string[]; detail?: string; offer_session_allow?: boolean; gate_id: number; gate_cause?: string; risk?: "read" | "write" | "destructive" | "high" | "credential_access" | "unknown"; human_only: boolean; generation?: number; lease_required: boolean; task_id?: string; exec_trust?: { computer_id: string; computer_name?: string; realm: string; label: string }; rules?: { rule_ids: string[]; outcome: "ask" | "unchecked"; reason?: string }; helper_id?: string; parent_tool_call_id?: string } } };
  /** The decision requirements of the PARKED gate changed (the approver lease was acquired, taken over, renewed past expiry or released while a gate is parked): {gate_id, generation, lease_required, helper_id?}. A client that captured the gate at park time refreshes what its decision must carry. On a helper_gates session each parked helper confirm is re-announced too, with its helper_id. */
  "decision_requirements": { session_id: string; seq: number; incarnation?: string; turn_id?: string; gate?: Record<string, unknown>; event: { type: "event.decision_requirements"; data: { gate_id: number; generation: number; lease_required: boolean; helper_id?: string } } };
  /** Directory-access scope changed/locked. */
  "dir_scope": { session_id: string; seq: number; incarnation?: string; turn_id?: string; gate?: Record<string, unknown>; event: { type: "event.dir_scope"; data: Record<string, unknown> } };
  /** A peer client detached from this shared live session (multi-attach presence). */
  "client_left": { session_id: string; seq: number; incarnation?: string; turn_id?: string; gate?: Record<string, unknown>; event: { type: "event.client_left"; data: Record<string, unknown> } };
  /** A delegated turn went quiet past the stall window but is still running (not fatal, not an error). */
  "delegated_idle": { session_id: string; seq: number; incarnation?: string; turn_id?: string; gate?: Record<string, unknown>; event: { type: "event.delegated_idle"; data: { agent: string; idle_ms: number; message: string } } };
  /** Session error (e.g. join_not_ready). */
  "error": { session_id: string; seq: number; incarnation?: string; turn_id?: string; gate?: Record<string, unknown>; event: { type: "event.error"; data: { message: string; code?: string; diag?: { provider?: string; model?: string; base_url?: string; key_source?: string; key_prefix?: string; http_status?: number; retryable?: boolean; attempts?: number; req_id?: string; err_code?: "timeout" | "rate_limit" | "auth" | "network" | "provider" | "canceled" | "context_overflow" | "provider_incomplete_response" | "max_tokens" | "bad_tool_args" | "unknown"; stop_reason?: string; last_error?: string }; max_steps?: number; reason?: string; retry_after_secs?: number; retry_at?: string; spend_cap_usd?: number; spent_usd?: number; resume_run_id?: string } } };
  /** A parked confirm/question gate was resolved (possibly by another attached client). */
  "gate_resolved": { session_id: string; seq: number; incarnation?: string; turn_id?: string; gate?: Record<string, unknown>; event: { type: "event.gate_resolved"; data: { kind: "confirm" | "question"; gate_id?: number; question_id?: number; outcome?: "answered" | "cancelled" | "yolo" | "timeout"; provenance?: "decision" | "yolo" | "cancelled" | "closed" | "context_cancelled" | "timeout"; holder?: string; generation?: number; request_id?: string; helper_id?: string; parent_tool_call_id?: string; task_id?: string; decision?: { approved?: boolean; persist_dirs?: boolean; session_scope?: boolean; trust_computer?: boolean; remember?: boolean; superseded?: boolean }; session_scope_applied?: boolean; note?: string } } };
