  "late_usage": { session_id: string; seq: number; incarnation?: string; turn_id?: string; gate?: Record<string, unknown>; event: { type: "event.late_usage"; data: { turn_id: string; input_tokens: number; output_tokens: number; cache_creation_tokens: number; cache_read_tokens: number } } };
  /** Fusion member trajectory progress. Not sent while the fusion runs inside a silent workflow step. */
