  /** Assistant text stream complete. */
  "stream_done": { session_id: string; seq: number; incarnation?: string; turn_id?: string; gate?: Record<string, unknown>; event: { type: "event.stream_done"; data: { input_tokens: number; output_tokens: number; cache_creation_tokens: number; cache_read_tokens: number; elapsed_ms: number; context_window?: number; context_estimated?: boolean; context_input_tokens?: number; cost_usd?: number; total_cost_usd?: number; background?: boolean; usage_only?: boolean; run_id?: string; helper_id?: string; parent_tool_call_id?: string } } };
  /** Profile sync status. */
  "sync_status": { session_id: string; seq: number; incarnation?: string; turn_id?: string; gate?: Record<string, unknown>; event: { type: "event.sync_status"; data: Record<string, unknown> } };
  /** Background task activity. */
